// ── Helper Function to Retrieve Book Profile by Slug ──────────────────────
export function getBookBySlug(slug: string): LibraryBook | null {
  const found = ALL_LIBRARY_BOOKS.find((b) => b.slug === slug)
  if (!found) return null
  return found
}
